findings.codeql_raw_query:
/**
 * @name Argument injection in subprocess
 * @description Traces data flow from command line arguments to subprocess calls
 * @kind path-problem
 * @problem.severity warning
 * @id py/subprocess-arg-injection
 * @tags security
 *        external/cwe/cwe-078
 *        external/cwe/cwe-088
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SubprocessArgConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Command line arguments as source
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
    or
    source = API::moduleImport("argparse").getMember("ArgumentParser").getACall().getReturn().getMember("parse_args").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["check_call", "check_output", "call", "Popen", "run"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SubprocessArgFlow = TaintTracking::Global<SubprocessArgConfig>;
import SubprocessArgFlow::PathGraph

from SubprocessArgFlow::PathNode source, SubprocessArgFlow::PathNode sink
where SubprocessArgFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Argument injection from $@.", source.getNode(), "command line arguments"
